pair<int, int> bfs_far(int src) {
    vector<int> dist(n + 1, -1);
    queue<int> q;
    q.push(src);
    dist[src] = 0;

    int best = src;
    while (!q.empty()) {
        int u = q.front();
        q.pop();

        if (dist[u] > dist[best]) best = u;

        for (int v : adj[u]) {
            if (dist[v] != -1) continue;
            dist[v] = dist[u] + 1;
            q.push(v);
        }
    }

    return {best, dist[best]};
}

