vector<int> tin(n + 1, -1), low(n + 1, -1), is_cut(n + 1, 0);
int timer = 0;

void dfs(int u, int p) {
    tin[u] = low[u] = timer++;
    int children = 0;

    for (int v : adj[u]) {
        if (v == p) continue;

        if (tin[v] != -1) {
            low[u] = min(low[u], tin[v]);
        } else {
            dfs(v, u);
            low[u] = min(low[u], low[v]);
            if (p != -1 && low[v] >= tin[u]) is_cut[u] = 1;
            children++;
        }
    }

    if (p == -1 && children > 1) is_cut[u] = 1;
}

